const state={role:'citizen',view:'citizen-home',submitted:false,verified:false,accepted:false};
const challenges=[
 {id:'SS-1042',title:'Contaminated drinking water near Ward 12',category:'Water',icon:'💧',place:'Pune, Maharashtra',people:428,status:'Under Review',cls:'progress',priority:'High',desc:'Residents report foul-smelling tap water for the last seven days. Several children have developed stomach illness.',progress:45},
 {id:'SS-1038',title:'Unsafe pedestrian crossing outside public school',category:'Road Safety',icon:'🚸',place:'Nashik, Maharashtra',people:215,status:'University Matched',cls:'verified',priority:'High',desc:'The school entrance opens onto a high-speed road without a marked crossing or warning system.',progress:67},
 {id:'SS-1029',title:'Overflowing community waste collection point',category:'Waste',icon:'♻️',place:'Nagpur, Maharashtra',people:164,status:'Pilot in Progress',cls:'progress',priority:'Medium',desc:'Irregular pickup causes overflow, odour and animals scattering waste into the surrounding lane.',progress:82},
 {id:'SS-1015',title:'Streetlights not working in three lanes',category:'Infrastructure',icon:'💡',place:'Aurangabad, Maharashtra',people:97,status:'Resolved',cls:'resolved',priority:'Medium',desc:'Non-functional lights create unsafe walking conditions after sunset.',progress:100}
];
const navs={citizen:[['citizen-home','⌂','Overview'],['explore','⌕','Explore challenges'],['my-reports','▣','My reports'],['impact','◫','Impact dashboard']],admin:[['admin-home','⌂','Verification queue'],['all-challenges','▦','All challenges'],['matching','◎','University matching'],['impact','◫','Impact dashboard']],university:[['university-home','⌂','Recommended challenges'],['active-projects','◈','Active projects'],['impact','◫','Impact dashboard']]};
const roles={citizen:{name:'Aarav Kumar',type:'Citizen',avatar:'AK',eyebrow:'CITIZEN PORTAL'},admin:{name:'District Moderator',type:'Admin',avatar:'DM',eyebrow:'ADMIN CONSOLE'},university:{name:'Tech University',type:'University',avatar:'TC',eyebrow:'UNIVERSITY HUB'}};
const content=document.getElementById('content');
function status(s,c){return `<span class="status ${c}">${s}</span>`}
function challengeRow(c){return `<article class="challenge-row" data-challenge="${c.id}"><span class="category-icon">${c.icon}</span><div><h3>${c.title}</h3><div class="meta">${c.id} · ${c.place} · ${c.people} supporters</div></div>${status(c.status,c.cls)}</article>`}
function stats(items){return `<section class="stats">${items.map(x=>`<article class="stat-card"><span class="stat-icon">${x[0]}</span><strong>${x[1]}</strong><small>${x[2]}</small></article>`).join('')}</section>`}
function citizenHome(){return `<section class="hero-strip"><div><h2>Turn a local problem into collective action.</h2><p>Report a challenge in your community. We connect verified problems with university teams that can research, prototype and pilot practical solutions.</p></div><button class="primary-button" data-action="report">Report a challenge →</button></section>${stats([['▣','03','My reports'],['◉','642','People supported'],['◈','01','Solution in progress'],['✓','01','Resolved']])}<section class="grid-2"><div class="panel"><div class="panel-head"><h2>Your recent challenges</h2><button class="text-button" data-view="my-reports">View all</button></div><div class="challenge-list">${challenges.slice(0,3).map(challengeRow).join('')}</div></div><div class="panel"><div class="panel-head"><h2>How Samadhan Setu works</h2></div><div class="journey"><div class="journey-step done"><span class="journey-dot">✓</span><div><strong>Citizen reports</strong><small>Problem, photo and location shared</small></div></div><div class="journey-step current"><span class="journey-dot">2</span><div><strong>AI-assisted review</strong><small>Category, urgency and duplicates identified</small></div></div><div class="journey-step"><span class="journey-dot">3</span><div><strong>Admin verifies</strong><small>Evidence checked by local authority</small></div></div><div class="journey-step"><span class="journey-dot">4</span><div><strong>University solves</strong><small>Team prototypes and pilots a solution</small></div></div></div></div></section>`}
function explore(title='Explore community challenges'){return `<div class="panel-head"><div><span class="eyebrow">PUBLIC CHALLENGES</span><h2>${title}</h2></div></div><div class="filters"><button class="filter active">All</button><button class="filter">Water</button><button class="filter">Waste</button><button class="filter">Road Safety</button><button class="filter">Infrastructure</button></div><section class="cards-grid">${challenges.map(c=>`<article class="challenge-card" data-challenge="${c.id}"><div class="challenge-card-top"><span class="category-icon">${c.icon}</span>${status(c.status,c.cls)}</div><h3>${c.title}</h3><p>${c.desc}</p><div class="meta">${c.place} · ${c.people} supporters</div><div class="progress-bar"><i style="width:${c.progress}%"></i></div><div class="meta">${c.progress}% journey complete</div></article>`).join('')}</section>`}
function adminHome(){let c=challenges[0];return `${stats([['▣','12','Awaiting review'],['⚑','04','High priority'],['◎','07','Possible duplicates'],['✓','38','Verified this month']])}<section class="grid-2"><div class="panel"><div class="panel-head"><h2>Priority verification queue</h2><span class="priority high">High priority first</span></div><div class="challenge-list">${challenges.slice(0,3).map(challengeRow).join('')}</div></div><div class="panel"><div class="panel-head"><h2>AI review summary</h2></div><div class="ai-card"><span class="spark">✦</span><div><strong>Water · High urgency</strong><small>92% classification confidence</small></div></div><p class="meta">The Ward 12 report mentions health symptoms, prolonged contamination and 428 affected residents.</p><div class="detail-block"><h3>POSSIBLE DUPLICATES</h3><p><strong>3 similar reports</strong><br><span class="meta">within a 1.2 km radius</span></p></div><div class="form-actions"><button class="primary-button" data-challenge="${c.id}">Review case</button></div></div></section>`}
function matching(){return `<div class="panel-head"><div><span class="eyebrow">SMART MATCHING</span><h2>University recommendations</h2></div><span class="priority high">For ${challenges[0].id}</span></div><section class="grid-2"><div class="panel"><h2>Challenge requirements</h2><p>${challenges[0].title}</p><div class="badge-row"><span class="skill-badge">Water testing</span><span class="skill-badge">IoT sensors</span><span class="skill-badge">Public health</span><span class="skill-badge">Within 100 km</span></div></div><div class="panel"><div class="match-card"><div><span class="eyebrow">BEST MATCH</span><h3>Pune Institute of Technology</h3><p class="meta">Civil & Environmental Engineering · 18 km away</p><div class="badge-row"><span class="skill-badge">Water Quality Lab</span><span class="skill-badge">12 faculty experts</span></div></div><span class="match-score">94%</span></div><div class="form-actions"><button class="primary-button" data-action="assign">Send invitation</button></div></div></section>`}
function universityHome(){return `<section class="hero-strip"><div><h2>Apply campus expertise to a real community need.</h2><p>These verified challenges match your departments, facilities and location. Accept one to create a faculty-guided student project.</p></div></section>${stats([['◎','06','Recommended'],['◈','02','Active projects'],['♟','18','Students involved'],['✓','03','Pilots completed']])}<div class="panel"><div class="panel-head"><h2>Recommended for your university</h2><span class="status verified">Expertise matched</span></div><section class="cards-grid">${challenges.slice(0,3).map((c,i)=>`<article class="challenge-card"><div class="challenge-card-top"><span class="category-icon">${c.icon}</span><span class="match-score">${[94,88,81][i]}%</span></div><h3>${c.title}</h3><p>${c.desc}</p><div class="badge-row"><span class="skill-badge">${c.category} expertise</span><span class="skill-badge">Nearby district</span></div><div class="form-actions"><button class="primary-button" data-action="accept" data-id="${c.id}">View & accept</button></div></article>`).join('')}</section></div>`}
function activeProjects(){return `<div class="panel-head"><div><span class="eyebrow">PROJECT WORKSPACE</span><h2>Active university projects</h2></div></div><section class="cards-grid"><article class="challenge-card"><div class="challenge-card-top"><span class="category-icon">🚸</span>${status('Prototype stage','progress')}</div><h3>Smart pedestrian warning system</h3><p>Student team is testing a solar-powered flashing sign and speed sensor outside the school.</p><div class="progress-bar"><i style="width:67%"></i></div><div class="meta">Milestone 3 of 5 · Pilot planned 18 Sep</div><div class="form-actions"><button class="secondary-button" data-action="milestone">Update milestone</button></div></article></section>`}
function impact(){return `${stats([['▣','1,284','Challenges reported'],['✓','468','Verified'],['◈','126','University projects'],['♟','2.4L','Citizens reached']])}<section class="analytics-grid"><div class="panel"><div class="panel-head"><div><span class="eyebrow">7-MONTH TREND</span><h2>Solutions completed</h2></div><div class="metric-ribbon"><strong>↗ 23%</strong><span>vs previous period</span></div></div><div class="line-chart-wrap"><svg class="line-chart" viewBox="0 0 700 250" role="img" aria-label="Solutions completed increased from 36 in March to 110 in September"><defs><linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#4f8ff1"/><stop offset="100%" stop-color="#c2dcff" stop-opacity="0"/></linearGradient></defs><g class="chart-grid"><line x1="48" y1="35" x2="670" y2="35"/><line x1="48" y1="88" x2="670" y2="88"/><line x1="48" y1="141" x2="670" y2="141"/><line x1="48" y1="194" x2="670" y2="194"/></g><path class="area-fill" d="M55 177 C105 165 130 146 155 148 S235 164 255 151 S330 116 355 110 S430 133 455 119 S530 80 555 77 S625 48 655 42 L655 210 L55 210 Z"/><path class="trend-line" pathLength="1" d="M55 177 C105 165 130 146 155 148 S235 164 255 151 S330 116 355 110 S430 133 455 119 S530 80 555 77 S625 48 655 42"/>${[[55,177,36],[155,148,52],[255,151,48],[355,110,75],[455,119,66],[555,77,91],[655,42,110]].map(p=>`<circle class="trend-dot" cx="${p[0]}" cy="${p[1]}" r="5" data-value="${p[2]} solutions"/>`).join('')}${['Mar','Apr','May','Jun','Jul','Aug','Sep'].map((m,i)=>`<text class="axis-label" x="${55+i*100}" y="238" text-anchor="middle">${m}</text>`).join('')}</svg><div class="chart-tooltip"></div></div></div><div class="panel"><div class="panel-head"><div><span class="eyebrow">CATEGORY MIX</span><h2>Impact distribution</h2></div></div><div class="donut-layout"><svg class="donut" viewBox="0 0 120 120" role="img" aria-label="Impact distribution by category"><circle class="donut-bg" cx="60" cy="60" r="45"/><circle class="donut-segment" cx="60" cy="60" r="45" stroke="#2563eb" pathLength="100" stroke-dasharray="32 68"/><circle class="donut-segment" cx="60" cy="60" r="45" stroke="#11a77c" pathLength="100" stroke-dasharray="25 75" stroke-dashoffset="-32"/><circle class="donut-segment" cx="60" cy="60" r="45" stroke="#f19a38" pathLength="100" stroke-dasharray="19 81" stroke-dashoffset="-57"/><circle class="donut-segment" cx="60" cy="60" r="45" stroke="#8058dc" pathLength="100" stroke-dasharray="14 86" stroke-dashoffset="-76"/><circle class="donut-segment" cx="60" cy="60" r="45" stroke="#a8b6c9" pathLength="100" stroke-dasharray="10 90" stroke-dashoffset="-90"/></svg><div class="donut-center"><strong>468</strong><small>verified cases</small></div></div><div class="legend">${[['#2563eb','Water','32%'],['#11a77c','Waste','25%'],['#f19a38','Road safety','19%'],['#8058dc','Infrastructure','14%'],['#a8b6c9','Other','10%']].map(x=>`<div class="legend-item"><i class="legend-dot" style="background:${x[0]}"></i><span>${x[1]}</span><strong>${x[2]}</strong></div>`).join('')}</div></div></section>`}
function animateView(){if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;if(window.gsap){gsap.from('.content > *',{opacity:0,y:18,duration:.55,stagger:.08,ease:'power3.out'});gsap.from('.stat-card',{opacity:0,scale:.94,duration:.5,stagger:.06,ease:'back.out(1.4)'});if(document.querySelector('.trend-line')){gsap.fromTo('.trend-line',{strokeDasharray:1,strokeDashoffset:1},{strokeDashoffset:0,duration:1.35,ease:'power2.out'});gsap.from('.trend-dot',{scale:0,transformOrigin:'center',duration:.4,stagger:.1,delay:.65,ease:'back.out(2)'});gsap.from('.donut-segment',{strokeDasharray:'0 100',duration:1.1,stagger:.1,ease:'power2.out'})}}document.querySelectorAll('.trend-dot').forEach(dot=>{dot.addEventListener('mouseenter',e=>{const tip=document.querySelector('.chart-tooltip');tip.textContent=e.target.dataset.value;tip.style.display='block';tip.style.left=`${e.target.cx.baseVal.value/7}%`;tip.style.top=`${e.target.cy.baseVal.value-15}px`});dot.addEventListener('mouseleave',()=>document.querySelector('.chart-tooltip').style.display='none')})}
function render(){let r=roles[state.role];document.getElementById('roleName').textContent=r.name;document.getElementById('roleType').textContent=r.type;document.getElementById('roleAvatar').textContent=r.avatar;document.getElementById('pageEyebrow').textContent=r.eyebrow;const titles={'citizen-home':'Good morning, Aarav','explore':'Explore challenges','my-reports':'My reports','impact':'Community impact','admin-home':'Verification queue','all-challenges':'All challenges','matching':'University matching','university-home':'Recommended challenges','active-projects':'Active projects'};document.getElementById('pageTitle').textContent=titles[state.view]||'Samadhan Setu';document.getElementById('nav').innerHTML=`<span class="nav-label">NAVIGATION</span>`+navs[state.role].map(n=>`<button class="nav-item ${state.view===n[0]?'active':''}" data-view="${n[0]}"><span class="nav-icon">${n[1]}</span>${n[2]}</button>`).join('');let html='';if(state.view==='citizen-home')html=citizenHome();else if(['explore','my-reports','all-challenges'].includes(state.view))html=explore(state.view==='my-reports'?'My submitted reports':state.view==='all-challenges'?'All verified challenges':undefined);else if(state.view==='admin-home')html=adminHome();else if(state.view==='matching')html=matching();else if(state.view==='university-home')html=universityHome();else if(state.view==='active-projects')html=activeProjects();else html=impact();content.innerHTML=html;requestAnimationFrame(animateView)}
function reportModal(){openModal(`<span class="eyebrow">STEP 1 OF 2</span><h2>Report a community challenge</h2><p class="meta">Share enough detail for the district team to verify the problem.</p><form id="reportForm"><div class="form-grid"><div class="field full"><label>Challenge title</label><input required value="Contaminated drinking water near Ward 12"></div><div class="field"><label>Category</label><select><option>Water & sanitation</option><option>Waste management</option><option>Road safety</option></select></div><div class="field"><label>Location</label><input value="Ward 12, Pune, Maharashtra"></div><div class="field full"><label>Describe the problem</label><textarea required>Tap water has had a foul smell and yellow colour for seven days. Several families have reported stomach illness.</textarea></div><div class="field full"><label>Evidence</label><div class="upload-box">📷 &nbsp; water-sample.jpg attached · Demo file</div></div></div><div class="form-actions"><button type="button" class="secondary-button" data-close>Cancel</button><button class="primary-button">Analyse & submit →</button></div></form>`)}
function detailModal(c){openModal(`<div class="detail-head"><div><span class="eyebrow">${c.id} · ${c.category.toUpperCase()}</span><h2>${c.title}</h2></div>${status(c.status,c.cls)}</div><div class="ai-card"><span class="spark">✦</span><div><strong>AI-assisted triage: ${c.priority} priority</strong><small>Category confidence 92% · 3 possible duplicate reports nearby</small></div></div><div class="detail-grid"><div class="detail-block"><h3>CITIZEN DESCRIPTION</h3><p>${c.desc}</p></div><div class="detail-block"><h3>COMMUNITY SIGNAL</h3><p><strong>${c.people} supporters</strong><br><span class="meta">${c.place}</span></p></div></div>${state.role==='admin'?`<div class="form-actions"><button class="secondary-button" data-action="reject">Request clarification</button><button class="primary-button" data-action="verify">Verify & find university →</button></div>`:''}`)}
function acceptModal(id){let c=challenges.find(x=>x.id===id);openModal(`<span class="eyebrow">UNIVERSITY PROJECT INVITATION</span><h2>${c.title}</h2><p>${c.desc}</p><div class="detail-block"><h3>SUGGESTED PROJECT</h3><p>Build and pilot a low-cost monitoring or intervention prototype with a faculty mentor and 4–6 students over 8 weeks.</p></div><div class="form-actions"><button class="secondary-button" data-close>Not now</button><button class="primary-button" data-action="confirm-accept">Accept challenge</button></div>`)}
function openModal(html){document.getElementById('modalContent').innerHTML=html;document.getElementById('modalBackdrop').hidden=false}function closeModal(){document.getElementById('modalBackdrop').hidden=true}function toast(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}
document.addEventListener('click',e=>{let view=e.target.closest('[data-view]');if(view){state.view=view.dataset.view;render();document.getElementById('sidebar').classList.remove('open')}let role=e.target.closest('[data-role]');if(role){state.role=role.dataset.role;state.view=role.dataset.role==='citizen'?'citizen-home':role.dataset.role==='admin'?'admin-home':'university-home';document.getElementById('roleMenu').classList.remove('open');render()}let action=e.target.closest('[data-action]');if(action){let a=action.dataset.action;if(a==='report')reportModal();if(a==='assign'){toast('Invitation sent to Pune Institute of Technology');state.role='university';state.view='university-home';render()}if(a==='accept')acceptModal(action.dataset.id);if(a==='confirm-accept'){closeModal();toast('Challenge accepted — project workspace created');state.view='active-projects';render()}if(a==='verify'){closeModal();toast('Challenge verified — university matches ready');state.view='matching';render()}if(a==='reject'){closeModal();toast('Clarification request saved');}if(a==='milestone')toast('Milestone updated for demo')}let ch=e.target.closest('[data-challenge]');if(ch)detailModal(challenges.find(x=>x.id===ch.dataset.challenge));if(e.target.closest('[data-close]'))closeModal()});
document.getElementById('roleButton').onclick=()=>document.getElementById('roleMenu').classList.toggle('open');document.getElementById('modalClose').onclick=closeModal;document.getElementById('modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()};document.getElementById('menuToggle').onclick=()=>document.getElementById('sidebar').classList.toggle('open');document.addEventListener('submit',e=>{if(e.target.id==='reportForm'){e.preventDefault();document.getElementById('modalContent').innerHTML=`<div class="success-screen"><div class="success-icon">✓</div><span class="eyebrow">REPORT SUBMITTED</span><h2>Your challenge is now under review</h2><p>Our prototype classified it as <strong>Water & sanitation</strong> with <strong>High priority</strong>. The district moderator will check the evidence next.</p><span class="ticket">Tracking ID: SS-1042</span><br><button class="primary-button" data-close>Back to dashboard</button></div>`;toast('Report submitted successfully')}});render();
